BASE="/tmp/claude-0/-home-user-fl-family-law-authority/7ac3e289-c815-5f2d-9278-ecc0918a4dd6/scratchpad"
bodies=os.path.join(BASE,"bodies")
OUT=os.path.join(BASE,"final_posts"); os.makedirs(OUT,exist_ok=True)

# shell from an existing final page (header+footer+js, correct domain/nav)
shell=open(os.path.join(BASE,"final","blog.html")).read()
HEAD=shell.split("<main>",1)[0]
